{"draft":{"version":"a1","html":"<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Pop the Bubbles</title>
<style>
  html, body {
    margin: 0;
    padding: 0;
    width: 100%;
    height: 100%;
    background: #fbf7ee;
    overflow: hidden;
    font-family: "Arial Narrow", Arial, sans-serif;
  }
  #wrap {
    position: fixed;
    inset: 0;
    width: 100vw;
    height: 100dvh;
  }
  canvas {
    display: block;
    width: 100%;
    height: 100%;
    touch-action: none;
  }
  #clearBtn {
    position: fixed;
    top: max(10px, env(safe-area-inset-top));
    right: 12px;
    z-index: 10;
    min-height: 44px;
    min-width: 100px;
    padding: 8px 16px;
    background: #fbf7ee;
    border: 3px solid #0078bf;
    color: #0078bf;
    font-weight: 900;
    font-size: 16px;
    letter-spacing: 0.5px;
    font-family: "Arial Narrow", Arial, sans-serif;
    border-radius: 8px;
    cursor: pointer;
    touch-action: manipulation;
  }
  #clearBtn:active {
    background: #0078bf;
    color: #fbf7ee;
  }
</style>
</head>
<body>
<div id="wrap">
  <canvas id="game"></canvas>
</div>
<button id="clearBtn" type="button">CLEAR</button>
<script>
  const CARTRIDGE = {
    send(type, payload = {}) {
      window.parent.postMessage(
        { source: "cartridge", v: 1, type, payload },
        "*",
      );
    },
  };
</script>
<script>
(function() {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const clearBtn = document.getElementById('clearBtn');
  let dpr = Math.max(1, window.devicePixelRatio || 1);
  let W = 0, H = 0;

  let running = false;
  let paused = false;

  // ---- grain tile (pre-rendered once) ----
  let grainCanvas = document.createElement('canvas');
  function buildGrain() {
    const size = 128;
    grainCanvas.width = size;
    grainCanvas.height = size;
    const gctx = grainCanvas.getContext('2d');
    const imgData = gctx.createImageData(size, size);
    for (let i = 0; i < imgData.data.length; i += 4) {
      const v = Math.floor(Math.random() * 255);
      imgData.data[i] = v;
      imgData.data[i + 1] = v;
      imgData.data[i + 2] = v;
      imgData.data[i + 3] = 255;
    }
    gctx.putImageData(imgData, 0, 0);
  }
  buildGrain();

  function resize() {
    dpr = Math.max(1, window.devicePixelRatio || 1);
    W = window.innerWidth;
    H = window.innerHeight;
    canvas.width = Math.floor(W * dpr);
    canvas.height = Math.floor(H * dpr);
    canvas.style.width = W + 'px';
    canvas.style.height = H + 'px';
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }
  window.addEventListener('resize', resize);
  resize();

  // ---- bubbles (pieces) ----
  const bubbles = [];
  let tally = 0;
  const INKS = ['#ff48b0', '#0078bf'];

  function rand(a, b) { return a + Math.random() * (b - a); }

  function spawnBubble() {
    const r = rand(28, 52);
    const x = rand(r + 4, W - r - 4);
    const y = H + r + rand(0, 200);
    bubbles.push({
      x, y, r,
      vy: -rand(18, 40) / 60,
      wobble: rand(0, Math.PI * 2),
      wobbleSpeed: rand(0.01, 0.03),
      ink: INKS[Math.floor(Math.random() * INKS.length)],
      pop: 0 // pop animation progress, 0 = alive
    });
  }

  function ensureBubbles() {
    const target = Math.min(9, 5 + Math.floor(tally / 10));
    while (bubbles.filter(b => b.pop === 0).length < target) {
      spawnBubble();
    }
  }

  function settle(list) {
    for (let i = list.length - 1; i >= 0; i--) {
      const b = list[i];
      if (b.pop > 0) {
        b.pop += 0.08;
        if (b.pop >= 1) {
          list.splice(i, 1);
        }
        continue;
      }
      b.y += b.vy;
      b.wobble += b.wobbleSpeed;
      b.x += Math.sin(b.wobble) * 0.3;
      if (b.y < -b.r - 20) {
        list.splice(i, 1);
      }
    }
    ensureBubbles();
  }

  function popAt(x, y) {
    for (let i = bubbles.length - 1; i >= 0; i--) {
      const b = bubbles[i];
      if (b.pop > 0) continue;
      const dx = b.x - x, dy = b.y - y;
      if (dx * dx + dy * dy <= b.r * b.r * 1.3) {
        b.pop = 0.001;
        tally += 1;
        CARTRIDGE.send('score', { value: tally });
        return true;
      }
    }
    return false;
  }

  // Clear-the-table: one function used by BOTH the host reset command
  // and the visible in-game CLEAR button.
  function clearTable() {
    bubbles.length = 0;
    tally = 0;
    CARTRIDGE.send('score', { value: 0 });
    ensureBubbles();
    draw();
  }

  // ---- drawing ----
  function drawHalftoneShade(cx, cy, r, color) {
    // simple halftone dots for a shade ring, avoiding gradients
    ctx.fillStyle = color;
    const dots = 10;
    for (let i = 0; i < dots; i++) {
      const ang = (i / dots) * Math.PI * 2;
      const dx = cx + Math.cos(ang) * r * 0.6;
      const dy = cy + Math.sin(ang) * r * 0.6;
      ctx.beginPath();
      ctx.arc(dx, dy, r * 0.06, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  function drawBubble(b) {
    ctx.save();
    if (b.pop > 0) {
      const p = b.pop;
      const rr = b.r * (1 + p * 0.6);
      ctx.globalAlpha = Math.max(0, 1 - p);
      // pop burst: a few offset rings
      ctx.strokeStyle = b.ink;
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.arc(b.x, b.y, rr, 0, Math.PI * 2);
      ctx.stroke();
      ctx.beginPath();
      ctx.arc(b.x + 2, b.y - 2, rr * 0.7, 0, Math.PI * 2);
      ctx.strokeStyle = '#0078bf';
      ctx.stroke();
      ctx.restore();
      return;
    }
    // misregistration offset layer
    ctx.globalAlpha = 1;
    ctx.fillStyle = b.ink === INKS[0] ? '#0078bf' : '#ff48b0';
    ctx.beginPath();
    ctx.arc(b.x + 2, b.y + 2, b.r, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = b.ink;
    ctx.beginPath();
    ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
    ctx.fill();

    // highlight shading via halftone dots (overlap color)
    drawHalftoneShade(b.x - b.r * 0.3, b.y - b.r * 0.3, b.r, '#5b3a8c');

    ctx.restore();
  }

  function draw() {
    ctx.clearRect(0, 0, W, H);
    ctx.fillStyle = '#fbf7ee';
    ctx.fillRect(0, 0, W, H);

    for (const b of bubbles) drawBubble(b);

    // Title & tally text
    ctx.fillStyle = '#0078bf';
    ctx.font = '900 22px "Arial Narrow", Arial, sans-serif';
    ctx.textBaseline = 'top';
    ctx.fillText('POP THE BUBBLES', 14, 14);

    ctx.fillStyle = '#ff48b0';
    ctx.font = '900 34px "Arial Narrow", Arial, sans-serif';
    ctx.fillText('Pops: ' + tally, 14, 44);

    if (!running) {
      const alpha = 0.55 + 0.45 * Math.sin(Date.now() / 300);
      ctx.save();
      ctx.globalAlpha = alpha;
      ctx.fillStyle = '#5b3a8c';
      ctx.font = '900 28px "Arial Narrow", Arial, sans-serif';
      const msg = 'Tap to begin';
      const w = ctx.measureText(msg).width;
      ctx.fillText(msg, (W - w) / 2, H / 2 - 14);
      ctx.restore();
    }

    // grain overlay
    ctx.save();
    ctx.globalAlpha = 0.08;
    const gsize = 128;
    for (let gx = 0; gx < W; gx += gsize) {
      for (let gy = 0; gy < H; gy += gsize) {
        ctx.drawImage(grainCanvas, gx, gy, gsize, gsize);
      }
    }
    ctx.restore();
  }

  function frame() {
    if (!paused) {
      if (running) settle(bubbles);
      draw();
    }
    requestAnimationFrame(frame);
  }

  // ---- input ----
  canvas.style.touchAction = 'none';
  canvas.addEventListener('pointerdown', (event) => {
    event.preventDefault();
    if (paused) return;
    const rect = canvas.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;
    if (!running) {
      running = true;
      ensureBubbles();
      CARTRIDGE.send('start');
      return;
    }
    popAt(x, y);
  });

  // Visible in-game control: calls the same clearTable function used by reset.
  clearBtn.addEventListener('click', clearTable);
  clearBtn.addEventListener('pointerdown', (e) => {
    e.stopPropagation();
  });

  // ---- host bridge ----
  function backToTitle() {
    running = false;
    paused = false;
    clearTable();
  }

  window.addEventListener('message', (event) => {
    const data = event.data;
    if (!data || data.source !== 'cartridge-host') return;
    if (data.type === 'pause') paused = true;
    if (data.type === 'resume') paused = false;
    if (data.type === 'reset') backToTitle();
  });

  // ---- boot ----
  ensureBubbles();
  draw();
  CARTRIDGE.send('boot', { title: 'Pop the Bubbles', gameType: 'toy-box', lang: 'en' });
  requestAnimationFrame(frame);
})();
</script>
</body>
</html>
"}}

